var BASE='https://a37p.oqd79.com';
var AKEY='B77A9FF7F323B5404902102257503C2F';
var IKEY='46cc793c53dc451b';
var HDR={'Content-Type':'application/json','Did':'1','Auth':'null','Referer':'https://www.4e63v.com/','Origin':'https://www.4e63v.com'};
eval(getCryptoJS());
function aesEnc(s){
  return CryptoJS.AES.encrypt(CryptoJS.enc.Utf8.parse(s),CryptoJS.enc.Utf8.parse(AKEY),{iv:CryptoJS.enc.Utf8.parse(AKEY.substr(0,16)),mode:CryptoJS.mode.CBC,padding:CryptoJS.pad.Pkcs7}).toString();
}
function api(path,obj,ts){
  var body=JSON.stringify({endata:aesEnc(JSON.stringify(obj)),ents:aesEnc(String(ts))});
  return fetch(BASE+path,{method:'POST',headers:HDR,body:body,timeout:15000});
}
function getTs(){
  var ts=0;
  try{ ts=JSON.parse(getResCode()).data.timeStamp; }catch(e){}
  if(!ts){ try{ ts=JSON.parse(fetch(BASE+'/base/getTimeStamp',{method:'POST',headers:HDR,body:'{}',timeout:10000})).data.timeStamp; }catch(e2){} }
  if(!ts){ ts=Math.floor(new Date().getTime()/1000)-28800; }
  return ts;
}
var CLASS_NAMES=['全部','国产','主播','日韩','欧美','动漫'];
var CLASS_IDS=[0,4,11,17,23,29];
function resolveType(v){
  v=String(v==null?'':v);
  try{ v=decodeURIComponent(v); }catch(e0){}
  v=v.replace(/^\s+|\s+$/g,'');
  if(!v||v==='全部') return 0;
  if(/^[0-9]+$/.test(v)) return parseInt(v,10);
  for(var i=0;i<CLASS_NAMES.length;i++){ if(CLASS_NAMES[i]===v) return CLASS_IDS[i]; }
  return 0;
}
